import { environment as buildEnvironment } from './environment';
import { environment as prodEnvironment } from './environment.prod';
import { environment as testEnvironment } from './environment.test';

type AppEnvironment = typeof buildEnvironment;

function readEnvFromQueryString(): string {
  if (typeof window === 'undefined') return '';
  const env = new URLSearchParams(window.location.search).get('env');
  return (env || '').trim().toLowerCase();
}

export function resolveRuntimeEnvironment(): AppEnvironment {
  const env = readEnvFromQueryString();

  if (env === 'prod' || env === 'production') {
    return prodEnvironment;
  }

  if (env === 'test' || env === 'qa' || env === 'homolog' || env === 'hml' || env === 'dev' || env === 'development') {
    return testEnvironment;
  }

  return buildEnvironment;
}

